import sqlite3

from miniweb import App, abortar

POR_PAGINA_PADRAO = 5
POR_PAGINA_MAXIMO = 20


def ler_inteiro(consulta, nome, padrao, maximo=None):
    texto = consulta.get(nome)
    if texto is None:
        return padrao
    if not texto.isdigit() or int(texto) < 1:
        raise ValueError(f"{nome} precisa ser um número inteiro maior que zero")
    valor = int(texto)
    if maximo is not None and valor > maximo:
        raise ValueError(f"{nome} pode ser no máximo {maximo}")
    return valor


def filtro_genero(genero):
    if genero is None:
        return "", ()
    return " WHERE genero = ?", (genero,)


class RepositorioJogos:
    def __init__(self, con):
        self.con = con

    def contar(self, genero):
        where, parametros = filtro_genero(genero)
        return self.con.execute("SELECT COUNT(*) FROM jogos" + where, parametros).fetchone()[0]

    def pagina(self, genero, limite, deslocamento):
        where, parametros = filtro_genero(genero)
        sql = "SELECT id, titulo, genero, preco FROM jogos" + where + " ORDER BY titulo LIMIT ? OFFSET ?"
        linhas = self.con.execute(sql, parametros + (limite, deslocamento)).fetchall()
        return [{"id": i, "titulo": t, "genero": g, "preco": p} for i, t, g, p in linhas]


def criar_app(con):
    app = App()
    repo = RepositorioJogos(con)

    @app.get("/jogos")
    def listar(req):
        try:
            pagina = ler_inteiro(req.consulta, "pagina", 1)
            por_pagina = ler_inteiro(req.consulta, "por_pagina", POR_PAGINA_PADRAO, POR_PAGINA_MAXIMO)
        except ValueError as e:
            abortar(400, str(e))
        genero = req.consulta.get("genero")
        itens = repo.pagina(genero, por_pagina, (pagina - 1) * por_pagina)
        return {"itens": itens, "pagina": pagina, "por_pagina": por_pagina, "total": repo.contar(genero)}

    return app


if __name__ == "__main__":
    con = sqlite3.connect("jogo.db")
    cliente = criar_app(con).cliente()
    for url in ["/jogos", "/jogos?pagina=2&por_pagina=5", "/jogos?genero=RPG&por_pagina=4&pagina=2", "/jogos?pagina=0"]:
        resp = cliente.get(url)
        print(url, resp.status, resp.json())

