        linha = self.con.execute(
            "SELECT u.id, u.nome, u.papel FROM tokens t JOIN usuarios u ON u.id = t.usuario_id WHERE t.token = ?",
            (token,),
        ).fetchone()
        if linha is None:
            return None
        return {"id": linha[0], "nome": linha[1], "papel": linha[2]}

    def listar_pontuacoes(self):
        linhas = self.con.execute("SELECT id, usuario_id, pontos FROM pontuacoes ORDER BY id").fetchall()
        return [{"id": i, "usuario_id": u, "pontos": p} for i, u, p in linhas]

    def buscar_pontuacao(self, id):
        linha = self.con.execute("SELECT id, usuario_id, pontos FROM pontuacoes WHERE id = ?", (id,)).fetchone()
        if linha is None:
            return None
        return {"id": linha[0], "usuario_id": linha[1], "pontos": linha[2]}

    def apagar_pontuacao(self, id):
        self.con.execute("DELETE FROM pontuacoes WHERE id = ?", (id,))
        self.con.commit()

    def listar_usuarios(self):
