ITERACOES = 10_000
ROTAS_PUBLICAS = {"/cadastro", "/login", "/ranking"}


def gerar_hash(senha):
    sal = secrets.token_hex(16)
    hash_hex = hashlib.pbkdf2_hmac("sha256", senha.encode(), sal.encode(), ITERACOES).hex()
    return sal + "$" + hash_hex


def conferir_senha(senha, guardado):
    partes = guardado.split("$")
    if len(partes) != 2:
        return False
    sal, hash_guardado = partes
    hash_hex = hashlib.pbkdf2_hmac("sha256", senha.encode(), sal.encode(), ITERACOES).hex()
    return hmac.compare_digest(hash_hex, hash_guardado)


