    repo = Repositorio(con)

    @app.antes
    def exigir_login(req):
        if req.caminho in ROTAS_PUBLICAS:
            return None
        cabecalho = req.cabecalho("Authorization", "")
        if not cabecalho.startswith("Bearer "):
            abortar(401, "faça login")
        usuario = repo.usuario_do_token(cabecalho[len("Bearer "):])
        if usuario is None:
            abortar(401, "token inválido")
        req.dados["usuario"] = usuario

    @app.post("/cadastro")
    def cadastro(req):
        try:
            nome, senha = validar_cadastro(req.json or {})
        except ValueError as e:
            abortar(400, str(e))
        if repo.buscar_por_nome(nome) is not None:
            abortar(409, "esse nome já está em uso")
        usuario_id = repo.criar_usuario(nome, gerar_hash(senha))
        return {"id": usuario_id, "nome": nome}, 201

    @app.post("/login")
    def login(req):
        dados = req.json or {}
        nome, senha = dados.get("nome"), dados.get("senha")
        if not isinstance(nome, str) or not isinstance(senha, str):
            abortar(400, "informe nome e senha")
        usuario = repo.buscar_por_nome(nome)
        if usuario is None or not conferir_senha(senha, usuario["senha_hash"]):
            abortar(401, "nome ou senha inválidos")
        token = secrets.token_hex(32)
        repo.salvar_token(token, usuario["id"])
        return {"token": token}

    @app.post("/pontuacoes")
    def enviar_pontos(req):
        try:
            pontos = validar_pontos(req.json or {})
        except ValueError as e:
            abortar(400, str(e))
        usuario = req.dados["usuario"]
        pontuacao_id = repo.registrar_pontos(usuario["id"], pontos)
        return {"id": pontuacao_id, "nome": usuario["nome"], "pontos": pontos}, 201

    @app.get("/ranking")
    def ranking(req):
        return repo.ranking()

    @app.delete("/conta")
    def apagar_conta(req):
        repo.apagar_usuario(req.dados["usuario"]["id"])
        return "", 204

    return app


